CREATE TABLE IF NOT EXISTS customer_booking_ids (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),business_id UUID NOT NULL REFERENCES businesses(id),first_name TEXT NOT NULL,last_name TEXT NOT NULL,email TEXT NOT NULL,date_of_birth DATE NOT NULL,phone TEXT NOT NULL DEFAULT '',member_number VARCHAR(8) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(business_id,member_number),UNIQUE(business_id,lower(first_name),lower(last_name),date_of_birth));
CREATE INDEX IF NOT EXISTS customer_booking_ids_email_idx ON customer_booking_ids(business_id,lower(email));
